const key = 'rhblyi90suxqqwfnnwzwy2tdvuhwqt09';
const args = {
  site: 'VN',
  nodeId: 11035861,
  monthSaleVolumeRangeMin: 30,
  priceRangeMin: 15000,
  page: 1
};
const body = JSON.stringify({ key, args });
const https = require('https');
const req = https.request({
  hostname: 'api.sorftime.com',
  path: '/open/shopee_product_search',
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
}, (res) => {
  let d = '';
  res.on('data', c => d += c);
  res.on('end', () => {
    try { console.log(JSON.stringify(JSON.parse(d), null, 2)); }
    catch(e) { console.log(d); }
  });
});
req.on('error', e => console.error(e));
req.write(body);
req.end();

